    tf:[["Stradlater is Holden's roommate.",true,"They share a room at Pencey."],["Holden feels nothing about Stradlater's date with Jane.",false,"He feels upset and worried about it."],["Holden's composition is about a baseball glove covered with poems.",true,"It describes Allie's glove in detail."],["Allie died in a car accident.",false,"He died of leukemia."],["Stradlater praises Holden's composition.",false,"He mocks it instead."],["Holden decides to leave Pencey immediately, that night.",true,"He packs his bags and leaves before morning."]],
